    public void Check(StepEdgeCurve edgeCurve, ShareTool shareTool, FrameworkCheck messageTool)
    {
        // 1- First Vertex != LastVertex but First VertexPoint == Last VertexPoint
        // Remark: time consuming process but useful.
        // If this append, we can drop one of the two vertices and replace it
        // everywhere it is referenced. Side effect: tolerance problem.
        if (AreEndsMatch(edgeCurve))
        {
            messageTool.AddWarning("Two instances of Vertex have equal (within uncertainty) coordinates");
        }

        if (!shareTool.IsShared(edgeCurve))
        {
            messageTool.AddFail("ERROR: EdgeCurve not referenced");
            return;
        }

        // 2- Two-Manifold Topology
        EntityIterator sharedEntitiesIt = shareTool.Sharings(edgeCurve);
        sharedEntitiesIt.SelectType(typeof(StepOrientedEdge), true);
        if (sharedEntitiesIt.NbEntities() != 2)
        {
            return;
        }

        StepOrientedEdge orientedEdge1 = sharedEntitiesIt.Value() as StepOrientedEdge;
        bool faceBoundOrientation1 = GetFaceBoundOrientation(orientedEdge1, shareTool);
        bool isCumulated1 = faceBoundOrientation1 != orientedEdge1.Orientation();

        sharedEntitiesIt.Next();

        StepOrientedEdge orientedEdge2 = sharedEntitiesIt.Value() as StepOrientedEdge;
        bool faceBoundOrientation2 = GetFaceBoundOrientation(orientedEdge2, shareTool);
        bool isCumulated2 = faceBoundOrientation2 != orientedEdge2.Orientation();

        // the orientation of the OrientedEdges must be opposite
        if (isCumulated1 == isCumulated2)
        {
            messageTool.AddFail("ERROR: non 2-manifold topology");
        }
    }

