    private static bool GetFaceBoundOrientation(StepOrientedEdge orientedEdge, ShareTool shareTool)
    {
        if (!shareTool.IsShared(orientedEdge))
        {
            return true;
        }

        StepEdgeLoop edgeLoop = GetSharing<StepEdgeLoop>(orientedEdge, shareTool);
        if (!shareTool.IsShared(edgeLoop))
        {
            return true;
        }

        StepFaceBound faceBound = GetSharing<StepFaceBound>(edgeLoop, shareTool);
        return (faceBound is null) ? true : faceBound.Orientation();
    }

    private static bool AreEndsMatch(StepEdgeCurve edgeCurve)
    {
        StepVertexPoint startVertex = edgeCurve.EdgeStart() as StepVertexPoint;
        StepVertexPoint endVertex = edgeCurve.EdgeEnd() as StepVertexPoint;
        if (startVertex == endVertex)
        {
            return false;
        }

        StepCartesianPoint startPoint = startVertex.VertexGeometry() as StepCartesianPoint;
        StepCartesianPoint endPoint = endVertex.VertexGeometry() as StepCartesianPoint;
        if ((startPoint is null) || (endPoint is null))
        {
            return false;
        }

        double distance = Math.Sqrt((startPoint.CoordinatesValue(1) - endPoint.CoordinatesValue(1)) * (startPoint.CoordinatesValue(1) - endPoint.CoordinatesValue(1)) + (startPoint.CoordinatesValue(2) - endPoint.CoordinatesValue(2)) * (startPoint.CoordinatesValue(2) - endPoint.CoordinatesValue(2)) + (startPoint.CoordinatesValue(3) - endPoint.CoordinatesValue(3)) * (startPoint.CoordinatesValue(3) - endPoint.CoordinatesValue(3)));
        return distance < global::Kerf.Engine.Foundation.Precision.Confusion();
    }
